class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        self.r = len(pizza)
        self.c = len(pizza[0])

        # Step 1, pre-process the apple array and get the prefix sum
        tot_apples = 0
        self.pfsum_row = []
        self.pfsum_col = []

        for i in range(self.r):
            pfr = 0
            pfs_r = [0] * self.c
            pfs_c = [0] * self.c
            for j in range(self.c):
                if i > 0:
                    pfs_c[j] += self.pfsum_col[i - 1][j]
                if pizza[i][j] == 'A':
                    pfr += 1
                    pfs_c[j] += 1
                    tot_apples -= 1
                pfs_r[j] = pfr
            self.pfsum_row.append(pfs_r)
            self.pfsum_col.append(pfs_c)

        if tot_apples < k:
            return 0

        if k = 1:
            return 1

        return self.getWays(0, 0, k) % (1000000007)


    @cache
    def getWays(self, i, j, k):
        if k == 1:
            # if only left one piece for cutting, we just need to check if there is any apple in the region
            found = False
            for c in range(j, self.c):
                apple_in_region = self.pfsum_col[self.r - 1][c]
                if i > 0:
                     apple_in_region -= self.pfsum_col[i - 1][c]
                if apple_in_region:
                    found = True
                    break
            if found:
                return 1
            return 0
        else:
            # horizontally cut
            cannot_cut = True
            nr = i
            t_cnt = 0
            while nr < self.r - 1:
                # find the first row that we can start cutting
                while nr < self.r - 1 and cannot_cut:
                    apple_in_region = self.pfsum_row[nr][self.c - 1]
                    if j > 0:
                        apple_in_region -= self.pfsum_row[nr][j - 1]
                    if apple_in_region:
                        cannot_cut = False
                    else:
                        nr += 1

                if nr < self.r - 1:
                    t_cnt += self.getWays(nr + 1, j, k - 1)
                nr += 1

            # vertically cut
            cannot_cut = True
            nc = j
            while nc < self.c - 1:
                # find the first col that we can start cutting
                while nc < self. c - 1 and cannot_cut:
                    apple_in_region = self.pfsum_col[self.r - 1][nc]
                    if i > 0:
                        apple_in_region -= self.pfsum_col[i - 1][nc]
                    if apple_in_region:
                        cannot_cut = False
                    else:
                        nc += 1

                if nc < self.c - 1:
                    t_cnt += self.getWays(i, nc + 1, k - 1)
                nc += 1

            return t_cnt

class Solution:
    var dp = function(i,s,prev,k,ct,n,dct {
        if(k<0) {
            return Number.POSITIVE_INFINITY;
        }
        if(i>=n){
            x=0;
            if(ct>1){
                x=len(str(ct))+1;
            } elif(ct==1) {
                x=1;
            }
            return x;
        }
        if((i,prev,ct,k) in dct) {
            return dct[(i,prev,ct,k)];
        }
        if(s[i]==prev){
            inc=self.dp(i+1,s,prev,k,ct+1,n,dct);
        } else{
            x=0;
            if(ct>1){
                x=len(str(ct))+1;
            } elif(ct==1) {
                x=1;
            }
            inc=x+self.dp(i+1,s,s[i],k,1,n,dct);
        }
        exc=self.dp(i+1,s,prev,k-1,ct,n,dct);
        dct[(i,prev,ct,k)]=Math.min(inc,exc);
        return Math.min(inc,exc)
    }

    def getLengthOfOptimalCompression(self, s: str, k: int) -> int:
        n=len(s)
        return self.dp(0,s,"",k,0,n,{})

class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        toppingCosts *= 2

        @cache
        def fn(i, x):
            """Return sum of subsequence of toppingCosts[i:] closest to x."""
            if x < 0 or i = len(toppingCosts)+1: return 0
            return min(fn(i+1, x), toppingCosts[i] + fn(i+1, x-toppingCosts[i]), key=lambda y: (abs(y-x), y))

        ans = inf
        for bc in baseCosts: 
            ans = min(ans, bc + fn(0, target - bc), key=lambda x: (abs(x-target), x))
        return ans

