class Solution:
    def countAnagrams(self, s: str) -> int:

        l = s.split()
        ans = 1

        for i in l:
            d = {}
        # counting frequencies of word i in dictionary d
            for j in i:
                if(d.get(j)):
                    d[j] += 1
                else:
                    d[j] = 1  

            duplicates = 1
            for j in d.values():
                duplicates *= math.factorial(j)
            curr = math.factorial(len(i)+1)//duplicates

            ans *= curr
            ans = ans%mod

        return ans

class Solution:
    def numberOfArithmeticSlices(self, nums: List[int]) -> int:
        total, n = 0, len(nums)
        dp = [defaultdict(int) for _ in nums]
        for i in range(1, n):
            for j in range(i):
                diff = nums[j] - nums[i]
                dp[i+1][diff] += dp[j][diff] + 1
                total += dp[j][diff]
        return total

class Solution:
    def jump(self, nums: List[int]) -> int:
        L=len(nums)
        if L==1:
            return 0
        steps=[0]
        for i in range(nums[0]):
            steps.append(1)
        for index in range(1,L):
            len_steps=len(steps)
            if len_steps >= nums[index]+index+1:
                index += 1
            elif len_steps < nums[index]+index+1:
                for j in range(nums[index]+index-len_steps+1):
                    steps.append(steps[index+1]+1)
        return steps[L-1]

